"""Customer portal routes."""


ROUTES = {
    "/": "home",
    "/pickups": "book_pickup",
    "/invoices": "list_invoices",
}


def resolve(path: str) -> str:
    return ROUTES.get(path.rstrip("/") or "/", "not_found")
